sys_script_include.script:
var ShowFLowUtils = Class.create();
ShowFLowUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getFlowContext: function() {
        var id = this.getParameter('sysparm_id');
        var tablename = this.getParameter('sysparm_tablename');
        var ctx = new GlideRecord("sys_flow_context");
        ctx.addEncodedQuery("source_table=" + tablename + "^source_record=" + id);
        ctx.query();
        if (ctx.next()) {
            var results = {
                "success": "true",
                "id": ctx.getUniqueValue()
            };
            return JSON.stringify(results);
        }
        gs.addErrorMessage("Flow Context does not exist for this record.");
        var results1 = {
            "success": "false"
        };
        return JSON.stringify(results1);
    },

    type: 'ShowFLowUtils'
});
